INSERT INTO `page_sections` (`id`, `page_id`, `section_key`, `section_type`, `title`, `subtitle`, `description`, `content_json`, `media_id`, `sort_order`, `is_visible`, `created_at`, `updated_at`, `category_id`, `version`, `is_deleted`) VALUES (1, 1, 'H01-hero', 'hero', '把想法，做成可验证的硬件', '工程从一块电路板开始', '企业名称（示例）关注 PCB 研发制作、嵌入式硬件和开源技术实践。页面中的产品均为结构演示示例。', '{\"note\": \"项目演示内容，不代表实际销售产品\", \"label\": \"页面首屏\", \"stamp\": \"AE / 01\", \"style\": \"default\", \"eyebrow\": \"HARDWARE / ENGINEERING\", \"imageFit\": \"contain\", \"background\": \"\", \"primaryHref\": \"/products\", \"primaryIcon\": \"ArrowUpRight\", \"primaryText\": \"查看产品\", \"imagePosition\": \"center\", \"secondaryHref\": \"/about\", \"secondaryIcon\": \"MoveRight\", \"secondaryText\": \"了解工程思路\", \"backgroundMedia\": \"\"}', 'media-home-hero', 1, 1, '2026-11-04 00:26:59', '2026-11-04 00:27:00', NULL, 1, 0);
INSERT INTO `page_sections` (`id`, `page_id`, `section_key`, `section_type`, `title`, `subtitle`, `description`, `content_json`, `media_id`, `sort_order`, `is_visible`, `created_at`, `updated_at`, `category_id`, `version`, `is_deleted`) VALUES (2, 1, 'H02-practice', 'editorial', '从电路设计开始理解一件硬件', '研发、制作与共享彼此连贯', '在需求、线路结构、板级原型与可阅读的技术资料之间建立清晰关系。', '{\"label\": \"工程笔记\", \"style\": \"default\", \"points\": [{\"id\": \"09b42212-3c7a-4982-8244-5eac5c626192\", \"text\": \"PCB 研发与方案整理\"}, {\"id\": \"29761eca-38df-4055-8495-0c595baa480c\", \"text\": \"电子硬件的制作探索\"}, {\"id\": \"f3e5798a-1386-491a-b729-eaa28d100116\", \"text\": \"技术内容记录与分享\"}], \"imageFit\": \"contain\", \"background\": \"\", \"imageCaption\": \"AE / CIRCUIT NOTE\", \"imagePosition\": \"center\", \"backgroundMedia\": \"\"}', 'media-home-engineering', 2, 1, '2026-11-04 00:26:59', '2026-11-04 00:27:00', NULL, 1, 0);
INSERT INTO `page_sections` (`id`, `page_id`, `section_key`, `section_type`, `title`, `subtitle`, `description`, `content_json`, `media_id`, `sort_order`, `is_visible`, `created_at`, `updated_at`, `category_id`, `version`, `is_deleted`) VALUES (3, 1, 'H03-shapes', 'board-showcase', '让不同的板型找到自己的空间', '形态、接口与用途并不相同', '计算核心适合集中算力，传感板着重测量位置，接入模块则需要直观的有线接口。', '{\"label\": \"板卡观察\", \"style\": \"default\", \"points\": [{\"id\": \"573663d2-8ef2-4ec4-815b-8830d1f8173f\", \"text\": \"紧凑核心板\"}, {\"id\": \"32e951f6-cd0f-4a13-b4ef-af736bde289e\", \"text\": \"隔离通信板\"}, {\"id\": \"0a2f5cf4-6024-43c6-b6b7-859713dba6e7\", \"text\": \"采样扩展板\"}, {\"id\": \"a20aa7e1-5325-410c-be64-f9d2bf732a13\", \"text\": \"控制功率板\"}], \"imageFit\": \"contain\", \"background\": \"\", \"imagePosition\": \"center\", \"backgroundMedia\": \"\"}', 'media-home-workbench', 3, 1, '2026-11-04 00:26:59', '2026-11-04 00:27:00', NULL, 1, 0);
INSERT INTO `page_sections` (`id`, `page_id`, `section_key`, `section_type`, `title`, `subtitle`, `description`, `content_json`, `media_id`, `sort_order`, `is_visible`, `created_at`, `updated_at`, `category_id`, `version`, `is_deleted`) VALUES (4, 1, 'H04-prototype', 'workflow', '先理解问题，再验证电路', '需求整理 / 设计推演 / 原型检查', '把实际使用场景转成可以检验的硬件要求。方案讨论、连接规划和原型试验彼此配合，帮助发现设计中的实际限制。', '{\"label\": \"开发路径\", \"steps\": [{\"id\": \"c9db9aeb-c4ae-4a58-bdf2-6eb3b46e9a3f\", \"text\": \"澄清需求\"}, {\"id\": \"0218e1c0-77ff-4c1b-af2a-24d098b05532\", \"text\": \"梳理信号\"}, {\"id\": \"1290a03c-6fa3-4ec2-b5db-a0e5dbf2daa6\", \"text\": \"布局电路\"}, {\"id\": \"96b98625-fe61-4016-bf95-5503b65b5c26\", \"text\": \"搭建验证\"}], \"style\": \"default\", \"imageFit\": \"contain\", \"background\": \"\", \"imagePosition\": \"center\", \"backgroundMedia\": \"\"}', NULL, 4, 1, '2026-11-04 00:26:59', '2026-11-04 00:27:00', NULL, 1, 0);
INSERT INTO `page_sections` (`id`, `page_id`, `section_key`, `section_type`, `title`, `subtitle`, `description`, `content_json`, `media_id`, `sort_order`, `is_visible`, `created_at`, `updated_at`, `category_id`, `version`, `is_deleted`) VALUES (5, 1, 'H05-layers', 'engineering', '看一条线路怎样组织', '分区、回流与连接都能被检查', '不同信号和供电区域需要合理安排。布局思路应结合材料叠层、连接需求和电路验证结果一起评估。', '{\"label\": \"线路设计\", \"style\": \"default\", \"points\": [{\"id\": \"f60b357e-6021-4274-9ee9-0055c3f31a53\", \"text\": \"电路功能分区\"}, {\"id\": \"05cc7889-809f-4d2c-bf25-418e4c96f1dd\", \"text\": \"焊盘与连接结构\"}, {\"id\": \"b2a6911f-78e2-4496-9d92-eb13e0a83648\", \"text\": \"布局与走线观察\"}], \"imageFit\": \"contain\", \"background\": \"\", \"imageCaption\": \"AE / CIRCUIT NOTE\", \"imagePosition\": \"center\", \"backgroundMedia\": \"\"}', 'media-home-engineering', 5, 1, '2026-11-04 00:26:59', '2026-11-04 00:27:00', NULL, 1, 0);
INSERT INTO `page_sections` (`id`, `page_id`, `section_key`, `section_type`, `title`, `subtitle`, `description`, `content_json`, `media_id`, `sort_order`, `is_visible`, `created_at`, `updated_at`, `category_id`, `version`, `is_deleted`) VALUES (6, 1, 'H06-making', 'craft', '制作经验来自可复用的细节', '选择元件之后，还要考虑装配方式', '焊接空间、机械固定和器件摆放会影响样机装配。以清楚的工程信息支持打样、制作和后续维护。', '{\"label\": \"制作细节\", \"style\": \"default\", \"points\": [{\"id\": \"0a1d91ee-a3b3-4268-bbd2-81d21aa8bc3c\", \"text\": \"板材与工艺选择\"}, {\"id\": \"fb427e66-a200-4273-be00-994cec8d1a89\", \"text\": \"器件装配位置\"}, {\"id\": \"051ab550-391c-44a6-8b93-c09d10542981\", \"text\": \"清楚的连接说明\"}], \"imageFit\": \"contain\", \"background\": \"\", \"imageCaption\": \"AE / CIRCUIT NOTE\", \"imagePosition\": \"center\", \"backgroundMedia\": \"\"}', 'media-about-assembly', 6, 1, '2026-11-04 00:26:59', '2026-11-04 00:27:00', NULL, 1, 0);
INSERT INTO `page_sections` (`id`, `page_id`, `section_key`, `section_type`, `title`, `subtitle`, `description`, `content_json`, `media_id`, `sort_order`, `is_visible`, `created_at`, `updated_at`, `category_id`, `version`, `is_deleted`) VALUES (7, 1, 'H07-validation', 'validation', '验证先于未经证实的结论', '记录现象，定位问题，保留依据', '以连接检查、基本功能验证和测试记录改进具体硬件设计，不以未经核验的认证、指标或测试成绩作宣传。', '{\"label\": \"测试验证\", \"style\": \"default\", \"points\": [{\"id\": \"91824056-d95d-432f-86e6-6c531f687def\", \"text\": \"检查接口方向\"}, {\"id\": \"f483ef83-946b-436d-aa1d-a4ffb628ba49\", \"text\": \"观察供电与状态\"}, {\"id\": \"3bd045a3-8638-4879-a170-e8545ce6fb07\", \"text\": \"记录真实测试过程\"}], \"imageFit\": \"contain\", \"background\": \"\", \"imagePosition\": \"center\", \"backgroundMedia\": \"\", \"validationStatus\": \"检查记录\"}', 'media-home-testbench', 7, 1, '2026-11-04 00:26:59', '2026-11-04 00:27:00', NULL, 1, 0);
INSERT INTO `page_sections` (`id`, `page_id`, `section_key`, `section_type`, `title`, `subtitle`, `description`, `content_json`, `media_id`, `sort_order`, `is_visible`, `created_at`, `updated_at`, `category_id`, `version`, `is_deleted`) VALUES (8, 1, 'H08-open', 'principles', '开放设计让学习过程更清楚', '让线路、接口与使用资料容易理解', '可读的设计说明有利于学习、复查和技术交流。具体项目的源文件、发布方式和开源许可须以真实确认的信息为准。', '{\"label\": \"设计原则\", \"style\": \"default\", \"points\": [{\"id\": \"e2de21af-d424-49c3-81b5-85654b70cf09\", \"text\": \"阅读工程资料\"}, {\"id\": \"173015f1-a3d4-4b91-9566-86aaf916ef78\", \"text\": \"交换实践经验\"}, {\"id\": \"a58c72f7-1b5c-4dde-a404-29c262fb2c03\", \"text\": \"积累学习笔记\"}], \"imageFit\": \"contain\", \"background\": \"\", \"imagePosition\": \"center\", \"backgroundMedia\": \"\"}', 'media-about-research', 8, 1, '2026-11-04 00:26:59', '2026-11-04 00:27:00', NULL, 1, 0);
INSERT INTO `page_sections` (`id`, `page_id`, `section_key`, `section_type`, `title`, `subtitle`, `description`, `content_json`, `media_id`, `sort_order`, `is_visible`, `created_at`, `updated_at`, `category_id`, `version`, `is_deleted`) VALUES (9, 1, 'H09-application', 'applications', '从实验桌到设备边缘', '聚焦合法开发、设备验证与教学实践', '板级硬件能够支撑嵌入式实验、自动化设备互联、边缘计算研究以及面向课程的测量和演示。', '{\"label\": \"应用方向\", \"style\": \"default\", \"points\": [{\"id\": \"549c0f74-85e2-40a4-841a-94ef89b9465d\", \"text\": \"嵌入式学习\"}, {\"id\": \"6df75ebf-828b-4749-9057-0e32e5baea26\", \"text\": \"通信研发\"}, {\"id\": \"c5317659-0488-41d1-a411-a3766964abd6\", \"text\": \"设备自动化\"}, {\"id\": \"00dc5f31-6d7e-4ce1-a20e-ff9c8c10150f\", \"text\": \"课程实验\"}], \"imageFit\": \"contain\", \"arrowIcon\": \"ArrowDownRight\", \"background\": \"\", \"imagePosition\": \"center\", \"backgroundMedia\": \"\"}', NULL, 9, 1, '2026-11-04 00:26:59', '2026-11-04 00:27:00', NULL, 1, 0);
INSERT INTO `page_sections` (`id`, `page_id`, `section_key`, `section_type`, `title`, `subtitle`, `description`, `content_json`, `media_id`, `sort_order`, `is_visible`, `created_at`, `updated_at`, `category_id`, `version`, `is_deleted`) VALUES (10, 1, 'H10-collaboration', 'collaboration', '合作始于把工程问题讲清', '可讨论的样机方向示例', '需求梳理、原型意见和后续验证均为通用项目协作示例，不构成企业对外服务范围或商业交付承诺。', '{\"label\": \"协作方式\", \"style\": \"default\", \"points\": [{\"id\": \"3cc96f3f-1769-42bc-b533-91e2b379ee44\", \"text\": \"沟通需求\"}, {\"id\": \"2318b8dc-795f-445f-bbd5-20ea902b72c3\", \"text\": \"讨论板级方案\"}, {\"id\": \"6431236e-e531-493d-8243-183b3697f00d\", \"text\": \"共同梳理验证问题\"}], \"status\": \"可编辑示例，不代表实际服务承诺\", \"imageFit\": \"contain\", \"arrowIcon\": \"ArrowDownRight\", \"background\": \"\", \"imagePosition\": \"center\", \"backgroundMedia\": \"\"}', NULL, 10, 1, '2026-11-04 00:26:59', '2026-11-04 00:27:00', NULL, 1, 0);
INSERT INTO `page_sections` (`id`, `page_id`, `section_key`, `section_type`, `title`, `subtitle`, `description`, `content_json`, `media_id`, `sort_order`, `is_visible`, `created_at`, `updated_at`, `category_id`, `version`, `is_deleted`) VALUES (11, 1, 'H11-principles', 'quote', '把连接关系做清楚，工程就更容易被继续', '好设计同时关照使用、验证与后期维护。', '硬件的价值不仅在于电路接通，还在于设计是否易于检查，结构是否支持后续制作，相关内容是否能够被真实理解。', '{\"note\": \"工程理念示例\", \"label\": \"工程引言\", \"style\": \"default\", \"imageFit\": \"contain\", \"background\": \"\", \"imagePosition\": \"center\", \"quoteReference\": \"ENGINEERING NOTE\", \"backgroundMedia\": \"\"}', 'media-about-precision', 11, 1, '2026-11-04 00:26:59', '2026-11-04 00:27:00', NULL, 1, 0);
INSERT INTO `page_sections` (`id`, `page_id`, `section_key`, `section_type`, `title`, `subtitle`, `description`, `content_json`, `media_id`, `sort_order`, `is_visible`, `created_at`, `updated_at`, `category_id`, `version`, `is_deleted`) VALUES (12, 1, 'H12-next', 'closing', '继续了解板卡和工程方法', '从产品矩阵观察不同电路设计', '查看独立的产品图像与类别说明，或进一步了解企业业务内容的示例组织方式。', '{\"label\": \"结尾导航\", \"links\": [\"products\", \"about\"], \"style\": \"default\", \"imageFit\": \"contain\", \"arrowIcon\": \"ArrowDownRight\", \"background\": \"\", \"primaryHref\": \"/products\", \"primaryIcon\": \"ArrowUpRight\", \"primaryText\": \"探索产品目录\", \"closingLabel\": \"下一个工程问题\", \"imagePosition\": \"center\", \"secondaryHref\": \"/about\", \"secondaryIcon\": \"MoveRight\", \"secondaryText\": \"了解工程方法\", \"backgroundMedia\": \"\"}', NULL, 12, 1, '2026-11-04 00:26:59', '2026-11-04 00:27:00', NULL, 1, 0);
INSERT INTO `page_sections` (`id`, `page_id`, `section_key`, `section_type`, `title`, `subtitle`, `description`, `content_json`, `media_id`, `sort_order`, `is_visible`, `created_at`, `updated_at`, `category_id`, `version`, `is_deleted`) VALUES (13, 2, 'P01-hero', 'hero', '为不同的工程问题，留出不同的板型', '九类板卡 / 四十五款原创结构示例', '每款产品图分别呈现芯片位置、接口数量、供电方式或板形变化。它们是技术演示素材，并非已量产或正式销售商品。', '{\"note\": \"全部名称与板卡仅用于示例展示\", \"label\": \"页面首屏\", \"stamp\": \"AE / 01\", \"style\": \"default\", \"eyebrow\": \"AN ORIGINAL HARDWARE INDEX\", \"imageFit\": \"contain\", \"background\": \"\", \"primaryHref\": \"#product-catalog\", \"primaryIcon\": \"ArrowUpRight\", \"primaryText\": \"浏览板卡目录\", \"imagePosition\": \"center\", \"secondaryHref\": \"/about\", \"secondaryIcon\": \"MoveRight\", \"secondaryText\": \"了解工程思路\", \"backgroundMedia\": \"\"}', 'media-home-engineering', 1, 1, '2026-11-04 00:26:59', '2026-11-04 00:27:00', NULL, 1, 0);
INSERT INTO `page_sections` (`id`, `page_id`, `section_key`, `section_type`, `title`, `subtitle`, `description`, `content_json`, `media_id`, `sort_order`, `is_visible`, `created_at`, `updated_at`, `category_id`, `version`, `is_deleted`) VALUES (14, 2, 'P02-categories', 'category-overview', '先从用途区分电路方向', '每个分类都围绕不同的硬件任务组织', '按计算、控制、通信、接口和实验等实际设计用途分组。通过类别快速跳转到当前产品页内的对应板卡。', '{\"label\": \"分类索引\", \"style\": \"default\", \"source\": \"product_categories\", \"imageFit\": \"contain\", \"arrowIcon\": \"ArrowDownRight\", \"background\": \"\", \"imagePosition\": \"center\", \"backgroundMedia\": \"\"}', NULL, 2, 1, '2026-11-04 00:26:59', '2026-11-04 00:27:00', NULL, 1, 0);
