INSERT INTO `page_sections` (`id`, `page_id`, `section_key`, `section_type`, `title`, `subtitle`, `description`, `content_json`, `media_id`, `sort_order`, `is_visible`, `created_at`, `updated_at`, `category_id`, `version`, `is_deleted`) VALUES (24, 2, 'P12-selection', 'selection-guide', '先看接口，再核对功率与空间', '为实际设备筛选提供可观察的出发点', '核对板卡能够接入的接口、输入输出电压和预留机械空间。需要无线研发时，提前确认实际使用环境与测试授权。', '{\"label\": \"选型提示\", \"style\": \"default\", \"points\": [{\"id\": \"7ebebc70-d16d-4fe5-b400-39221dfd2513\", \"text\": \"接口类型与数量\"}, {\"id\": \"ed0383e3-9a7f-40e3-80b1-8a6c2bac596c\", \"text\": \"供电方式和使用功率\"}, {\"id\": \"7b111d03-441e-41e2-b26d-7afabf542b12\", \"text\": \"设备尺寸与安装位置\"}, {\"id\": \"b8f12558-4bc2-42f6-a00a-1eb4eb965b62\", \"text\": \"后续调试方式\"}], \"imageFit\": \"contain\", \"arrowIcon\": \"ArrowDownRight\", \"background\": \"\", \"imagePosition\": \"center\", \"backgroundMedia\": \"\"}', NULL, 12, 1, '2026-11-04 00:26:59', '2026-11-04 00:27:00', NULL, 1, 0);
INSERT INTO `page_sections` (`id`, `page_id`, `section_key`, `section_type`, `title`, `subtitle`, `description`, `content_json`, `media_id`, `sort_order`, `is_visible`, `created_at`, `updated_at`, `category_id`, `version`, `is_deleted`) VALUES (25, 2, 'P13-end', 'closing', '板卡背后的方法也值得了解', '走进公司介绍，继续了解设计思路', '技术样例只有结合真实需求、实际约束和验证过程，才能成为可靠工程的一部分。', '{\"label\": \"结尾导航\", \"links\": [\"about\", \"home\"], \"style\": \"default\", \"imageFit\": \"contain\", \"arrowIcon\": \"ArrowDownRight\", \"background\": \"\", \"primaryHref\": \"/about\", \"primaryIcon\": \"ArrowUpRight\", \"primaryText\": \"继续阅读企业介绍\", \"closingLabel\": \"下一个工程问题\", \"imagePosition\": \"center\", \"secondaryHref\": \"/products\", \"secondaryIcon\": \"MoveRight\", \"secondaryText\": \"查看硬件示例\", \"backgroundMedia\": \"\"}', NULL, 13, 1, '2026-11-04 00:26:59', '2026-11-04 00:27:00', NULL, 1, 0);
INSERT INTO `page_sections` (`id`, `page_id`, `section_key`, `section_type`, `title`, `subtitle`, `description`, `content_json`, `media_id`, `sort_order`, `is_visible`, `created_at`, `updated_at`, `category_id`, `version`, `is_deleted`) VALUES (26, 3, 'A01-story', 'hero', '一块板，连接设计与实际应用', '硬件工程需要能够读懂和检验的细节', '企业名称（示例）是一家介绍电路板研发制作、嵌入式硬件设计探索和开源实践的示例企业名称，不是已经核实的现实主体。', '{\"note\": \"DESIGN / CIRCUIT / PRACTICE\", \"label\": \"页面首屏\", \"stamp\": \"AE / 01\", \"style\": \"default\", \"eyebrow\": \"DESIGN / CIRCUITS / SHARED KNOWLEDGE\", \"imageFit\": \"contain\", \"background\": \"\", \"primaryHref\": \"/products\", \"primaryIcon\": \"ArrowUpRight\", \"primaryText\": \"查看产品\", \"imagePosition\": \"center\", \"secondaryHref\": \"#about-methods\", \"secondaryIcon\": \"MoveRight\", \"secondaryText\": \"阅读工程方法\", \"backgroundMedia\": \"\"}', 'media-about-research', 1, 1, '2026-11-04 00:26:59', '2026-11-04 00:27:00', NULL, 1, 0);
INSERT INTO `page_sections` (`id`, `page_id`, `section_key`, `section_type`, `title`, `subtitle`, `description`, `content_json`, `media_id`, `sort_order`, `is_visible`, `created_at`, `updated_at`, `category_id`, `version`, `is_deleted`) VALUES (27, 3, 'A02-intro', 'editorial', '把硬件开发这件事说清楚', '先展示业务性质，而不是虚构企业历史', '业务方向覆盖 PCB 电路板的设计与制作、嵌入式控制原型以及硬件方案的技术验证，内容面对工程开发者和对电子产品感兴趣的访客。', '{\"label\": \"工程笔记\", \"style\": \"default\", \"points\": [{\"id\": \"e4754ea9-fc68-4d30-9547-8b249f2df14e\", \"text\": \"板级电路设计探索\"}, {\"id\": \"37d78053-7fdb-4c59-807e-b4b7bc5c1245\", \"text\": \"硬件原型研发\"}, {\"id\": \"73d07346-23c9-478e-8f2e-e343ed68886e\", \"text\": \"相关技术文档整理\"}], \"imageFit\": \"contain\", \"background\": \"\", \"imageCaption\": \"AE / CIRCUIT NOTE\", \"imagePosition\": \"center\", \"backgroundMedia\": \"\"}', NULL, 2, 1, '2026-11-04 00:26:59', '2026-11-04 00:27:00', NULL, 1, 0);
INSERT INTO `page_sections` (`id`, `page_id`, `section_key`, `section_type`, `title`, `subtitle`, `description`, `content_json`, `media_id`, `sort_order`, `is_visible`, `created_at`, `updated_at`, `category_id`, `version`, `is_deleted`) VALUES (28, 3, 'A03-stages', 'timeline', '从理解问题到持续改进', '以业务阶段说明典型研发逻辑', '下列阶段描述硬件项目的一般工作方式，不虚构具体年份、企业成立时间、真实事件或客户合作。', '{\"label\": \"工程过程\", \"steps\": [{\"id\": \"c20921d2-657b-4f63-9b37-84ebba0ff52a\", \"text\": \"探索：了解真实使用条件\"}, {\"id\": \"82ec8635-3ec0-4347-becb-09d6cbc2c3c7\", \"text\": \"原型：搭建第一版验证线路\"}, {\"id\": \"eb745250-585c-4d21-8b0c-6543a5582d7c\", \"text\": \"评估：记录测试现象与限制\"}, {\"id\": \"12e2d4e6-ed56-4ac2-9047-b393011a3c50\", \"text\": \"迭代：依据问题检查设计\"}], \"style\": \"default\", \"imageFit\": \"contain\", \"background\": \"\", \"imagePosition\": \"center\", \"backgroundMedia\": \"\"}', NULL, 3, 1, '2026-11-04 00:26:59', '2026-11-04 00:27:00', NULL, 1, 0);
INSERT INTO `page_sections` (`id`, `page_id`, `section_key`, `section_type`, `title`, `subtitle`, `description`, `content_json`, `media_id`, `sort_order`, `is_visible`, `created_at`, `updated_at`, `category_id`, `version`, `is_deleted`) VALUES (29, 3, 'A04-business', 'capabilities', '四类工作相互配合', '研发、电路板制作、系统联接与知识记录', '电路分析、布局安排、板级实现和设计说明彼此关联。把它们分开讨论，有助于明确每个阶段需要解决的问题。', '{\"label\": \"工作范围\", \"style\": \"default\", \"points\": [{\"id\": \"ce7c853f-229b-45b9-8225-01473ec3ba8a\", \"text\": \"需求与电路规划\"}, {\"id\": \"3c8fd49a-4c9f-49bd-acc3-f594bd24c2d0\", \"text\": \"PCB 设计与制作探索\"}, {\"id\": \"ffb7086a-3279-4e56-ac3b-00850af400ca\", \"text\": \"嵌入式系统连接\"}, {\"id\": \"c16d2962-b6b6-474f-bfa6-7438af5a3b76\", \"text\": \"技术资料整理\"}], \"imageFit\": \"contain\", \"arrowIcon\": \"ArrowDownRight\", \"background\": \"\", \"imagePosition\": \"center\", \"backgroundMedia\": \"\"}', NULL, 4, 1, '2026-11-04 00:26:59', '2026-11-04 00:27:00', NULL, 1, 0);
INSERT INTO `page_sections` (`id`, `page_id`, `section_key`, `section_type`, `title`, `subtitle`, `description`, `content_json`, `media_id`, `sort_order`, `is_visible`, `created_at`, `updated_at`, `category_id`, `version`, `is_deleted`) VALUES (30, 3, 'A05-method', 'editorial', '设计决策从使用场景出发', '先明确电路要连接的实际对象', '工程分析从输入输出、信号类型和工作环境入手，再逐步安排器件、线路和接口。按步骤检查约束，降低凭空堆砌规格的风险。', '{\"label\": \"工程笔记\", \"style\": \"default\", \"points\": [{\"id\": \"67b83b89-0431-4f09-8b2f-854665b45e17\", \"text\": \"确认应用场景\"}, {\"id\": \"92e9c7dc-0841-4400-a199-e048ddc6d588\", \"text\": \"整理信号关系\"}, {\"id\": \"7fe81b34-bbbf-4f1f-b938-2e191a7c235d\", \"text\": \"复核接口边界\"}], \"imageFit\": \"contain\", \"background\": \"\", \"imageCaption\": \"AE / CIRCUIT NOTE\", \"imagePosition\": \"center\", \"backgroundMedia\": \"\"}', 'media-home-engineering', 5, 1, '2026-11-04 00:26:59', '2026-11-04 00:27:00', NULL, 1, 0);
INSERT INTO `page_sections` (`id`, `page_id`, `section_key`, `section_type`, `title`, `subtitle`, `description`, `content_json`, `media_id`, `sort_order`, `is_visible`, `created_at`, `updated_at`, `category_id`, `version`, `is_deleted`) VALUES (31, 3, 'A06-functions', 'disciplines', '不同专业关注同一块板的不同部分', '硬件设计、嵌入式、测试、制作与文档', '将不同技术职能的工作目标说清楚，便于共享设计输入和记录问题。这里描述职能协同方式，不虚构具体员工身份和人数。', '{\"label\": \"专业分工\", \"style\": \"default\", \"points\": [{\"id\": \"52162a93-88b6-4cdb-9ee4-28d345f222fb\", \"text\": \"电路与 PCB 规划\"}, {\"id\": \"158003d1-5c22-4b9a-a9fd-2bd4f20f51e4\", \"text\": \"固件与系统协同\"}, {\"id\": \"e6528a81-f3e2-423f-9ba6-03a685790cd9\", \"text\": \"验证与测量记录\"}, {\"id\": \"ee39ed7c-75e7-4dbb-a943-86b99f722c12\", \"text\": \"装配与技术文档\"}], \"imageFit\": \"contain\", \"arrowIcon\": \"ArrowDownRight\", \"background\": \"\", \"imagePosition\": \"center\", \"backgroundMedia\": \"\"}', NULL, 6, 1, '2026-11-04 00:26:59', '2026-11-04 00:27:00', NULL, 1, 0);
INSERT INTO `page_sections` (`id`, `page_id`, `section_key`, `section_type`, `title`, `subtitle`, `description`, `content_json`, `media_id`, `sort_order`, `is_visible`, `created_at`, `updated_at`, `category_id`, `version`, `is_deleted`) VALUES (32, 3, 'A07-making', 'craft', '从纸面线路走向实际制作', '器件选择、装配位置与机械接口需要一起考虑', '设计应留出连接、焊接、固定和检查的空间。评估实际可制作性，有助于保持原型与预期电路功能一致。', '{\"label\": \"制作细节\", \"style\": \"default\", \"points\": [{\"id\": \"9ac4ce17-0561-4dbe-a3aa-5a79a649fe2a\", \"text\": \"考虑焊接和返修\"}, {\"id\": \"d6e67763-1eb6-4068-9222-b5bafb2a730b\", \"text\": \"明确机械固定位置\"}, {\"id\": \"5f6da6e8-00a3-429f-b1d3-19989aac34a0\", \"text\": \"评估接线和装配步骤\"}], \"imageFit\": \"contain\", \"background\": \"\", \"imageCaption\": \"AE / CIRCUIT NOTE\", \"imagePosition\": \"center\", \"backgroundMedia\": \"\"}', 'media-about-assembly', 7, 1, '2026-11-04 00:26:59', '2026-11-04 00:27:00', NULL, 1, 0);
INSERT INTO `page_sections` (`id`, `page_id`, `section_key`, `section_type`, `title`, `subtitle`, `description`, `content_json`, `media_id`, `sort_order`, `is_visible`, `created_at`, `updated_at`, `category_id`, `version`, `is_deleted`) VALUES (33, 3, 'A08-quality', 'validation', '质量判断需要可以复查的依据', '记录问题和状态，让结论能被再次核验', '针对供电、连接和基本功能进行对应检查。网站不公布未核实的合格率、认证结果和测试性能数据。', '{\"label\": \"测试验证\", \"style\": \"default\", \"points\": [{\"id\": \"5e334170-0c3f-437b-a953-0c6d1230667a\", \"text\": \"记录测试环境\"}, {\"id\": \"39f710c9-aef6-4166-8d56-01244dee443f\", \"text\": \"描述实际观察结果\"}, {\"id\": \"be0cf8a9-503a-4b7e-9cc0-fd6cbad02eb5\", \"text\": \"重新验证重要改动\"}], \"imageFit\": \"contain\", \"background\": \"\", \"imagePosition\": \"center\", \"backgroundMedia\": \"\", \"validationStatus\": \"检查记录\"}', 'media-about-precision', 8, 1, '2026-11-04 00:26:59', '2026-11-04 00:27:00', NULL, 1, 0);
INSERT INTO `page_sections` (`id`, `page_id`, `section_key`, `section_type`, `title`, `subtitle`, `description`, `content_json`, `media_id`, `sort_order`, `is_visible`, `created_at`, `updated_at`, `category_id`, `version`, `is_deleted`) VALUES (34, 3, 'A09-sharing', 'principles', '让看得懂的资料帮助知识传递', '可以分享的方法，比未经证实的承诺更有价值', '设计图纸和实用说明能够支持自学与协作。具体仓库、发布进度、许可方式及真实开放承诺应以经确认的项目信息为准。', '{\"label\": \"设计原则\", \"style\": \"default\", \"points\": [{\"id\": \"7069718c-f5e1-4166-8edd-c25210a51aea\", \"text\": \"整理读得懂的电路说明\"}, {\"id\": \"a909ed3e-68df-4fda-b89d-de9257bf289b\", \"text\": \"标出使用与限制条件\"}, {\"id\": \"446fb01b-f4c8-4221-91ed-1d91a9b14965\", \"text\": \"记录实际测试和变更\"}], \"imageFit\": \"contain\", \"background\": \"\", \"imagePosition\": \"center\", \"backgroundMedia\": \"\"}', NULL, 9, 1, '2026-11-04 00:26:59', '2026-11-04 00:27:00', NULL, 1, 0);
INSERT INTO `page_sections` (`id`, `page_id`, `section_key`, `section_type`, `title`, `subtitle`, `description`, `content_json`, `media_id`, `sort_order`, `is_visible`, `created_at`, `updated_at`, `category_id`, `version`, `is_deleted`) VALUES (35, 3, 'A10-collaborate', 'collaboration', '把需求变成可以共同判断的问题', '先沟通边界，再考虑工程方案', '技术协作通常需要确认应用需求、接口条件、验证方式和维护范围。本板块介绍通用项目思路，不表示已经提供某项具体商业服务。', '{\"label\": \"协作方式\", \"steps\": [{\"id\": \"d6b06f98-9c58-478f-85b1-c5e652a3accf\", \"text\": \"说明需求背景\"}, {\"id\": \"24c42e72-2a32-4d5a-8ac2-e0fc6c6f205e\", \"text\": \"澄清硬件接口\"}, {\"id\": \"1b6bc59d-d4c6-4803-8a65-d827ad477c23\", \"text\": \"讨论检查方式\"}], \"style\": \"default\", \"status\": \"工作过程示例\", \"imageFit\": \"contain\", \"arrowIcon\": \"ArrowDownRight\", \"background\": \"\", \"imagePosition\": \"center\", \"backgroundMedia\": \"\"}', NULL, 10, 1, '2026-11-04 00:26:59', '2026-11-04 00:27:00', NULL, 1, 0);
INSERT INTO `page_sections` (`id`, `page_id`, `section_key`, `section_type`, `title`, `subtitle`, `description`, `content_json`, `media_id`, `sort_order`, `is_visible`, `created_at`, `updated_at`, `category_id`, `version`, `is_deleted`) VALUES (36, 3, 'A11-responsibility', 'principles', '让电路更容易检查，也更容易继续维护', '清楚的设计能减少后续使用中的盲区', '关注材料消耗、零部件替换和设计可读性，是增加硬件工程寿命的实际方法。', '{\"label\": \"设计原则\", \"style\": \"default\", \"points\": [{\"id\": \"3e829100-49ae-4f56-b403-d7d3c46a33a5\", \"text\": \"减少不必要的复杂度\"}, {\"id\": \"9121cd8c-70bf-4396-bf8a-f5666e0a5de3\", \"text\": \"保留必要的工程说明\"}, {\"id\": \"7a5d40f0-1467-4fc4-ba84-44c1f3f6a905\", \"text\": \"考虑维修与设备升级\"}], \"imageFit\": \"contain\", \"background\": \"\", \"imagePosition\": \"center\", \"backgroundMedia\": \"\"}', NULL, 11, 1, '2026-11-04 00:26:59', '2026-11-04 00:27:00', NULL, 1, 0);
INSERT INTO `page_sections` (`id`, `page_id`, `section_key`, `section_type`, `title`, `subtitle`, `description`, `content_json`, `media_id`, `sort_order`, `is_visible`, `created_at`, `updated_at`, `category_id`, `version`, `is_deleted`) VALUES (37, 3, 'A12-future', 'closing', '未来继续探索可验证的硬件方案', '连接设计、制作与实际使用之间的经验', '以嵌入式计算、通信接口、能量管理和传感技术等方向作为研发关注示例，不构成已经确定的发展承诺。', '{\"label\": \"结尾导航\", \"links\": [\"products\", \"home\"], \"style\": \"default\", \"imageFit\": \"contain\", \"arrowIcon\": \"ArrowDownRight\", \"background\": \"\", \"primaryHref\": \"/products\", \"primaryIcon\": \"ArrowUpRight\", \"primaryText\": \"探索产品目录\", \"closingLabel\": \"下一个工程问题\", \"imagePosition\": \"center\", \"secondaryHref\": \"/about\", \"secondaryIcon\": \"MoveRight\", \"secondaryText\": \"了解工程方法\", \"backgroundMedia\": \"\"}', NULL, 12, 1, '2026-11-04 00:26:59', '2026-11-04 00:27:00', NULL, 1, 0);
