INSERT INTO `product_categories` (`id`, `slug`, `name`, `description`, `sort_order`, `is_visible`, `media_id`, `icon`, `version`, `is_deleted`) VALUES ('category-compute', 'compute', '单板计算与边缘计算', '从紧凑算力板到边缘接入原型，观察计算资源与外设之间的布局关系。', 1, 1, NULL, 'CircuitBoard', 1, 0);
INSERT INTO `product_categories` (`id`, `slug`, `name`, `description`, `sort_order`, `is_visible`, `media_id`, `icon`, `version`, `is_deleted`) VALUES ('category-control', 'control', '微控制器与嵌入式控制', '用于实时控制、低功耗交互和外围连接的可比较原型。', 2, 1, NULL, 'CircuitBoard', 1, 0);
