INSERT INTO `product_categories` (`id`, `slug`, `name`, `description`, `sort_order`, `is_visible`, `media_id`, `icon`, `version`, `is_deleted`) VALUES ('category-lab', 'lab', '专业实验与特殊硬件', '用于可编程逻辑、安全评估及产品验证的技术演示原型。', 9, 1, NULL, 'CircuitBoard', 1, 0);
INSERT INTO `product_categories` (`id`, `slug`, `name`, `description`, `sort_order`, `is_visible`, `media_id`, `icon`, `version`, `is_deleted`) VALUES ('category-motion', 'motion', '运动控制与自动化', '连接电机、执行机构和自动化样机的控制及功率硬件。', 7, 1, NULL, 'CircuitBoard', 1, 0);
INSERT INTO `product_categories` (`id`, `slug`, `name`, `description`, `sort_order`, `is_visible`, `media_id`, `icon`, `version`, `is_deleted`) VALUES ('category-network', 'network', '工业网络与通信接口', '用于接口隔离、设备互联和协议转换研究的板级方案。', 4, 1, NULL, 'CircuitBoard', 1, 0);
INSERT INTO `product_categories` (`id`, `slug`, `name`, `description`, `sort_order`, `is_visible`, `media_id`, `icon`, `version`, `is_deleted`) VALUES ('category-power', 'power', '电源管理与能量系统', '通过不同的转换、电池保护与安全隔离结构呈现电源管理思路。', 5, 1, NULL, 'CircuitBoard', 1, 0);
